SELECT COUNT(DISTINCT c.namelabel) 
FROM constructor_results cr
JOIN constructors c ON cr.unitnode = c.cstr_key;

SELECT COUNT(*) FROM (
    SELECT c.namelabel, COUNT(cr.unitnode) AS cnt
    FROM constructor_results cr
    JOIN constructors c ON cr.unitnode = c.cstr_key
    GROUP BY c.namelabel
) sub;

SELECT COUNT(DISTINCT contunit) FROM (
    SELECT contunit, SUM(scr_tot) as total_points
    FROM constructor_standings 
    GROUP BY contunit
    HAVING SUM(scr_tot) > 0
) sub;

SELECT COUNT(DISTINCT c.namelabel) 
FROM constructor_results cr
JOIN constructors c ON cr.unitnode = c.cstr_key
WHERE EXISTS (
    SELECT 1 FROM constructor_standings cs WHERE cs.contunit = c.cstr_key
);
